from pwn import remote
import time

def main():
    HOST, PORT = 'misc.chal.csaw.io', 5000
    conn = remote(HOST, PORT)

    # Step 1: Receive and input '8' for the number of bases
    data = conn.recvuntil(b'qubits:')
    print(data.decode())
    conn.sendline(b'8')
    data = conn.recvuntil(b'Enter bases:')
    print(data.decode())

    # Helper to send sequence and receive error count
    def try_seq(seq):
        conn.sendline(seq.encode())
        resp = b""
        while True:
            part = conn.recvline()
            resp += part
            # Look for a line with 'errors:' or equivalent feedback
            if b'error' in part.lower() or b'correct' in part.lower() or b'Try' in part or b'bases' in part or b'[' in part or b'flag{' in part:
                break
        print(resp.decode())
        # Attempt to get number from the error/correct line
        for line in resp.decode().split('\n'):
            if 'error' in line.lower():
                try:
                    num = int([s for s in line.split() if s.isdigit()][0])
                    return num, resp.decode()
                except Exception:
                    continue
            if 'correct' in line.lower():
                try:
                    nums = [int(s) for s in line.split() if s.isdigit()]
                    if nums:
                        return 8 - nums[0], resp.decode()
                except Exception:
                    continue
            if 'flag{' in line:
                return 0, resp.decode()
        # fallback
        return 99, resp.decode()

    # Step 2: Try 'ZZZZZZZZ' and note error count
    bases = ['Z'] * 8
    e, _ = try_seq(''.join(bases))
    print(f'Initial error count: {e}')

    # Step 3: Toggle bases one by one, see if error decreases
    for i in range(8):
        bases[i] = 'X' if bases[i] == 'Z' else 'Z'
        e2, resp = try_seq(''.join(bases))
        if e2 <= e:
            e = e2
            print(f'Position {i+1}, toggled, new errors: {e2}')
            # Stay flipped
        else:
            # Revert toggle
            bases[i] = 'X' if bases[i] == 'Z' else 'Z'
            print(f'Position {i+1}, reverted, errors: {e2}')

    # Repeat until error is 0 (with a hard stop just in case)
    attempt = 0
    while e != 0 and attempt < 10:
        for i in range(8):
            bases[i] = 'X' if bases[i] == 'Z' else 'Z'
            e2, resp = try_seq(''.join(bases))
            if e2 <= e:
                e = e2
            else:
                bases[i] = 'X' if bases[i] == 'Z' else 'Z'
        attempt += 1

    # Output the correct sequence and any extra output
    print(f'Correct base sequence: {"".join(bases)}')
    print('--- Additional Server Output ---')
    e3, final_out = try_seq(''.join(bases))
    print(final_out)

if __name__ == '__main__':
    main()

